import{_ as t,o as n,c as e,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"高速 PCB 设计中的信号完整性与电源完整性：从概念到落地措施","description":"","frontmatter":{},"headers":[],"relativePath":"notes/high-speed-pcb-si-pi.md","filePath":"notes/high-speed-pcb-si-pi.md","lastUpdated":1791206372000}'),l={name:"notes/high-speed-pcb-si-pi.md"};function s(i,a,p,d,o,h){return n(),e("div",null,[...a[0]||(a[0]=[r(`<h1 id="高速-pcb-设计中的信号完整性与电源完整性从概念到落地措施" tabindex="-1">高速 PCB 设计中的信号完整性与电源完整性：从概念到落地措施 <a class="header-anchor" href="#高速-pcb-设计中的信号完整性与电源完整性从概念到落地措施" aria-label="Permalink to &quot;高速 PCB 设计中的信号完整性与电源完整性：从概念到落地措施&quot;">​</a></h1><p>信号完整性（SI）和电源完整性（PI）是高速数字设计里绕不开的两件事，但很多人在做设计时被要求「满足 SI、PI 的要求」，其实并不清楚这两个词到底指什么。这份笔记从最基础的定义出发，一路走到可以在板子上落地的规避措施，中间覆盖高速信号的判定标准、七类典型的 SI 问题、以及电源完整性的几个关键数字。</p><p>全文按「先定义、再机理、最后措施」的顺序组织。每一章都可以单独看，但按顺序读会更顺——因为后面讲措施时，对的是前面讲过的现象。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200091847-c655ada0-2ed0-4de8-9925-12a5c25ec7fe.png" alt="封面"></p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#一先把-si-和-pi-说清楚">一、先把 SI 和 PI 说清楚</a></li><li><a href="#二传输线与返回路径">二、传输线与返回路径</a></li><li><a href="#三七类-si-问题现象机理与观测">三、七类 SI 问题：现象、机理与观测</a></li><li><a href="#四规避措施">四、规避措施</a></li><li><a href="#五电源完整性">五、电源完整性</a></li><li><a href="#六一页速查表">六、一页速查表</a></li></ul><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092170-7f05556f-25b6-45c2-b5fe-fb8eaa2f33a1.png" alt="全篇骨架"></p><hr><h2 id="一先把-si-和-pi-说清楚" tabindex="-1">一、先把 SI 和 PI 说清楚 <a class="header-anchor" href="#一先把-si-和-pi-说清楚" aria-label="Permalink to &quot;一、先把 SI 和 PI 说清楚&quot;">​</a></h2><h3 id="_11-信号完整性si" tabindex="-1">1.1 信号完整性（SI） <a class="header-anchor" href="#_11-信号完整性si" aria-label="Permalink to &quot;1.1 信号完整性（SI）&quot;">​</a></h3><p>信号完整性，指的是高速数字电路中，信号在传输过程中保持其完整性和准确性的能力。</p><p>说得直白一点：我这边给你什么波形，你那边就要收到什么波形——幅值、大小、方向（相位）都不许变。从 a 点传到 b 点，b 点收到的波形要跟 a 点发出去的<strong>一样</strong>。</p><h3 id="_12-电源完整性pi" tabindex="-1">1.2 电源完整性（PI） <a class="header-anchor" href="#_12-电源完整性pi" aria-label="Permalink to &quot;1.2 电源完整性（PI）&quot;">​</a></h3><p>电源完整性，指的是为芯片提供一个稳定、没有噪声的电源。</p><p>比如一个 5 伏直流，上面那些波动、抖动，就是噪声。只有正确供电之后，芯片才能稳定地工作。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092049-8e4ebcd8-0109-4de8-ad88-688e9eb4750f.png" alt="SI 与 PI 的定义"></p><h3 id="_13-一个信号要走完的完整路径" tabindex="-1">1.3 一个信号要走完的完整路径 <a class="header-anchor" href="#_13-一个信号要走完的完整路径" aria-label="Permalink to &quot;1.3 一个信号要走完的完整路径&quot;">​</a></h3><p>芯片输出之后，信号要穿过封装内部的导线、PCB 上的走线、背板或 FPC、连接器，最后才到接收芯片。</p><p>接收到的波形「还是这个样子」，只是多了一些抖动、毛刺。所以真正要判断的是两件事：能不能正确、没有误差地接收；抖动的范围有没有落在允许的范围之内。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092007-8c4fde0c-4c97-4c56-90e9-9c76e3dbf514.png" alt="信号路径"></p><h3 id="_14-三个考核量时序持续时间电压幅度" tabindex="-1">1.4 三个考核量：时序、持续时间、电压幅度 <a class="header-anchor" href="#_14-三个考核量时序持续时间电压幅度" aria-label="Permalink to &quot;1.4 三个考核量：时序、持续时间、电压幅度&quot;">​</a></h3><p>信号到达芯片接收管脚时，只要这三样都满足，就说明它满足了 SI 的需求。</p><ul><li><strong>时序</strong>：信号从这头走到那头允许用多少时间——比如开始计时，5 秒钟之后必须看到目标波形。走线时必须满足这个要求。</li><li><strong>持续时间</strong>：高电平持续几秒、低电平持续几秒，都算在时序要求里。</li><li><strong>电压幅度</strong>：高电平的幅度是多高，3.3 伏、5 伏、还是 12 伏。</li></ul><p>反过来：当信号不能正常响应，或者信号质量不能让系统长期稳定工作时，就出现了信号完整性问题。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092675-f5074e42-f77a-45bc-8519-bb93c0449fd1.png" alt="三个考核量"></p><h3 id="_15-si-的三要素信号芯片传输通道" tabindex="-1">1.5 SI 的三要素：信号、芯片、传输通道 <a class="header-anchor" href="#_15-si-的三要素信号芯片传输通道" aria-label="Permalink to &quot;1.5 SI 的三要素：信号、芯片、传输通道&quot;">​</a></h3><ul><li><strong>信号</strong>：被传输的主体。首先要了解、熟悉信号的特性——它传的是视频、音频还是别的什么。</li><li><strong>芯片</strong>：分驱动芯片和接收芯片，也就是源端和末端。驱动端负责发，接收端负责收。</li><li><strong>传输通道</strong>：信号所走的路。要保证信号在驱动芯片和接收芯片之间正确传输，就是「为信号修好路、搭好桥」。</li></ul><p>前两个，在电路设计阶段就已经定好了：信号是什么信号、源发出的信号长什么样，已经在电路设计里处理好了；驱动芯片是什么、接收芯片是什么，电路搭建的时候就已经准备好了。<strong>留给 PCB 工程师的只有第三个</strong>——怎么合理摆放器件、怎么合理布线，保证这条通道是通的。</p><p>落到具体动作上就是三句话：要不要做等长？要不要做阻抗？要不要打孔？</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092261-ce9ef589-7e3f-4c16-a220-f95f5d6f7f91.png" alt="SI 三要素"></p><h3 id="_16-广义-si-与狭义-si别把范围搞混" tabindex="-1">1.6 广义 SI 与狭义 SI：别把范围搞混 <a class="header-anchor" href="#_16-广义-si-与狭义-si别把范围搞混" aria-label="Permalink to &quot;1.6 广义 SI 与狭义 SI：别把范围搞混&quot;">​</a></h3><ul><li><strong>狭义 SI</strong>：关注信号传输的信号质量本身。我们平时说「要考虑信号完整性的信号」，指的就是高速信号。</li><li><strong>广义 SI</strong>：电路设计中互连线所引起的所有问题。既包含狭义的 SI，也包含电源完整性和电磁干扰。</li></ul><p>SI 问题主要表现成三类：</p><ul><li><strong>时序</strong>：信号延时、时钟偏移、时钟抖动。我们用时钟去采样信号，时钟一有波动、抖动、偏移，传输时间就跟着偏。</li><li><strong>噪声</strong>：振铃、反射、近端串扰、远端串扰、开关噪声、地弹、电源反弹、过冲、下冲、非单调性、色散、衰减。</li><li><strong>EMI</strong>：设备运行时产生的电磁干扰（辐射、传导），以及它自己的抗扰度：EMS、静电放电。</li></ul><p>产品层面的表现是：屏幕有抖动、闪屏，或者声音不对、刺耳。消费者感知到的是性能被影响，设计阶段表现为信号出了问题。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092465-0e7e9865-0e6f-49f4-b751-475695158deb.png" alt="广义 SI 与狭义 SI"></p><h3 id="_17-两条判定定义高速电路与高速信号" tabindex="-1">1.7 两条判定定义：高速电路与高速信号 <a class="header-anchor" href="#_17-两条判定定义高速电路与高速信号" aria-label="Permalink to &quot;1.7 两条判定定义：高速电路与高速信号&quot;">​</a></h3><ul><li><strong>高速电路</strong>：数字逻辑电路的频率超过 50 兆赫兹，并且工作在这个频率上的电路达到整个系统的 1/3 以上。</li><li><strong>高速信号</strong>：线传播的延时，大于数字信号驱动端上升时间的 1/2——就认为这个信号是高速信号。</li></ul><p>SI 只针对高速信号。单片机项目、电机驱动、风扇、小家电、智能手环这类电路，时钟工作频率很低，不用去考虑信号完整性问题。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092533-c21bbefd-66ef-4910-ae20-ed8f0320de15.png" alt="两条定义"></p><h3 id="_18-速算1-纳秒走-6000-mil" tabindex="-1">1.8 速算：1 纳秒走 6000 mil <a class="header-anchor" href="#_18-速算1-纳秒走-6000-mil" aria-label="Permalink to &quot;1.8 速算：1 纳秒走 6000 mil&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传输延时(ns) ≈ 走线长度(mil) ÷ 6000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>也就是说，PCB 上走 6000 密耳的长度，大约需要一个纳秒。</p><p>判定一个信号算不算高速信号，看传播延时：当信号的上升沿时间小于 2～6 倍的信号传播延时，就可以判断它是高速信号。上升时间从 IBIS 模型或数据手册提取，一般取幅度 10% → 90% 的时间范围（IBIS 里常取 20% → 80%）。</p><p>举个实例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.2 ns（上升沿）　vs　2000 mil ÷ 6000 = 0.33 ns</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>0.2 小于 2～6 倍的 0.33，所以是高速信号。同时得到一个常识：<strong>走线越短，传播延时越小，SI 问题还没来得及表现就结束了</strong>——所以走线越短越好。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092638-62d68cfe-9089-4463-af41-7d261cd15304.png" alt="传播延时速算"></p><hr><h2 id="二传输线与返回路径" tabindex="-1">二、传输线与返回路径 <a class="header-anchor" href="#二传输线与返回路径" aria-label="Permalink to &quot;二、传输线与返回路径&quot;">​</a></h2><h3 id="_21-什么是传输线" tabindex="-1">2.1 什么是传输线 <a class="header-anchor" href="#_21-什么是传输线" aria-label="Permalink to &quot;2.1 什么是传输线&quot;">​</a></h3><p>传输线，是由信号传输和回流组成的一组导体结构。只画一根线不构成回路，信号是传不出去的。</p><p>常见的传输线有双绞线、PCB 上的微带线和带状线。为什么我们平时看不见回流路径？因为直接把回路接成 GND，用铺一整块完整的地平面来给它解决了——回流其实一直在，只是在平面里。</p><p>传输线是微波电路的基础：本质上是<strong>考虑了寄生参数的交流电路</strong>。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092667-8d6ec21b-7244-47b8-8408-21926338c400.png" alt="传输线剖面"></p><h3 id="_22-和直流不一样两端电压电流都不同" tabindex="-1">2.2 和直流不一样：两端电压、电流都不同 <a class="header-anchor" href="#_22-和直流不一样两端电压电流都不同" aria-label="Permalink to &quot;2.2 和直流不一样：两端电压、电流都不同&quot;">​</a></h3><p>高频情况下，即使不考虑辐射，一段理想导线两端的电流也会不同。</p><ul><li><strong>电流为什么不同</strong>：两线之间的电容要充放电，充放电就引起电流变化——这是寄生参数。</li><li><strong>电压为什么不同</strong>：线上有寄生的串联电感，电感也会充放电，而且它还能储存能量。</li><li>再加上导体本身的损耗（寄生电阻），也会引起部分压降。</li></ul><p>直流看稳态，瞬态充放电可以不管；交流电流本身在变，瞬态充放电就必须考虑。所以结论是：<strong>频率越高 → 电流变化越快 → 瞬态充放电影响越大 → 越必须考虑传输线效应</strong>。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092954-f7c2f3d3-0870-47c6-951a-800523ffea64.png" alt="传输线等效 RLC"></p><h3 id="_23-微带线与带状线一个表层一个内层" tabindex="-1">2.3 微带线与带状线：一个表层，一个内层 <a class="header-anchor" href="#_23-微带线与带状线一个表层一个内层" aria-label="Permalink to &quot;2.3 微带线与带状线：一个表层，一个内层&quot;">​</a></h3><ul><li><strong>微带线</strong>走在表层，只有 1 个参考平面，另一面是空间（空气 εr ≈ 1）。</li><li><strong>带状线</strong>走在内层，上下各 1 个参考平面负责回流。</li></ul><p>区别直接决定了后面 3.9 节要讲的传播速度差异。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200092965-49b729e1-a18b-48a1-83a8-bd81ab368c93.png" alt="微带线与带状线"></p><h3 id="_24-研究回流时先放弃地这个概念" tabindex="-1">2.4 研究回流时，先放弃「地」这个概念 <a class="header-anchor" href="#_24-研究回流时先放弃地这个概念" aria-label="Permalink to &quot;2.4 研究回流时，先放弃「地」这个概念&quot;">​</a></h3><p>对于信号而言，传输线就是提供信号传输和回流的一组导体结构。研究回流时，我们改称它为「返回路径」——<strong>只要是导体就行</strong>。</p><p>能当返回路径的东西不止一种：</p><ol><li><strong>地平面</strong>：最常见的返回路径。</li><li><strong>电源平面</strong>：同样能作为参考、提供返回路径。</li><li><strong>旁边包的地线</strong>：信号线旁边包一根地线，它也能充当返回路径。</li><li><strong>差分线的另一根</strong>：两根差分线可以相互之间互为参考。</li><li><strong>走线层本身</strong>：PCB 的布局布线里，走线层也能充当返回平面。</li></ol><p>结论：返回路径只要是导电的、能让信号在上面传输的导体，都可以充当。</p><p>「信号路径」与「返回路径」只是一种习惯性的相对叫法——别被「地」这个字限制住思路。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093366-1eee98be-6ab4-4839-8d6a-e57c3e674167.png" alt="六类返回路径"></p><h3 id="_25-返回电流到底走哪儿" tabindex="-1">2.5 返回电流到底走哪儿 <a class="header-anchor" href="#_25-返回电流到底走哪儿" aria-label="Permalink to &quot;2.5 返回电流到底走哪儿&quot;">​</a></h3><ul><li>入射电流（信号源走过来的电流）与返回电流<strong>大小相等、方向相反</strong>。</li><li>返回电流是通过磁场耦合产生的。</li><li>当存在多个返回路径时，返回路径与信号的距离很大程度上决定了返回电流的大小——谁离得近，电流就往谁那儿走。</li></ul><p>所以返回电流并不在邻近走线上，而是<strong>集中在走线正下方的参考平面上</strong>。这就是为什么高速 PCB 设计里反复强调：走线下面邻近层要有一块完整的参考平面，最好是地平面——让返回电流尽量不要跟别的东西叠加。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093173-e06f5082-568a-4289-b73b-4e3f85c021db.png" alt="返回电流分布"></p><h3 id="_26-参考平面一定要是地吗" tabindex="-1">2.6 参考平面一定要是地吗 <a class="header-anchor" href="#_26-参考平面一定要是地吗" aria-label="Permalink to &quot;2.6 参考平面一定要是地吗&quot;">​</a></h3><p>参考平面是信号完整性里最重要的概念之一：它是在电路设计和分析中用来作为基准的某个特定物理位置或平面，用来定义信号的传播路径、评估传输特性。</p><p>这是困扰了很多工程师的问题——<strong>答案是不一定</strong>。参考平面为信号回流提供返回路径，只要是导体就行。</p><table tabindex="0"><thead><tr><th></th><th>地平面</th><th>电源平面</th></tr></thead><tbody><tr><td>电位</td><td>0 伏，是基准点</td><td>不是 0 伏，比如 3.3 V 就是 3.3 V 的电平</td></tr><tr><td>阻抗</td><td>低</td><td>相对高一些——阻抗不等于电压除以电流，电压不为 0，阻抗就偏高</td></tr><tr><td>适用</td><td>返回路径需要的是低阻抗路径，所以主要以地为主</td><td>可以作为参考：DDR 组件时，一般就可以拿电源平面来做参考平面</td></tr></tbody></table><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093168-7045a42a-9e73-445e-92de-c3aa3d8ddf3b.png" alt="参考平面一定要是地吗"></p><h3 id="_27-既然可以为什么大多数设计还是用地" tabindex="-1">2.7 既然可以，为什么大多数设计还是用地 <a class="header-anchor" href="#_27-既然可以为什么大多数设计还是用地" aria-label="Permalink to &quot;2.7 既然可以，为什么大多数设计还是用地&quot;">​</a></h3><p>原因主要有两个：</p><ul><li><strong>芯片内部参考的是地网络</strong>：多数芯片设计里，芯片内部参考的都是地网络。如果中途改用电源作参考，不可避免会出现跨平面分割，可能造成信号阻抗不连续，进而影响信号质量。</li><li><strong>避免 EMI 问题</strong>：表层器件参考第二层地、第四层参考电源，信号回流要经电容耦合回到接地才能形成完整回流路径。如果打孔位置刚好没有电容，这个路径就会变大，回路面积增大，EMI 随之变大。</li></ul><p>那电源平面是怎么回到地的？靠电容耦合。这个电容，可能是你的去耦电容，也可能是电源平面与地平面之间的平板电容——看哪个起主导作用。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C = ε0 · εr · S / d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>距离 d 越小，平板电容越大，耦合越好。所以用电源平面做参考时，要求接地层和 power 层挨得比较近，平板电容才明显。</p><p>配套动作：用电源平面做返回时，一定要通过电容，或者在过孔附近补上去耦电容；放去耦电容时也要均匀分布在被分割的平面上。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093438-d037ae84-dfc9-4b38-a563-887dcd8b84f0.png" alt="电源平面作参考"></p><hr><h2 id="三七类-si-问题现象机理与观测" tabindex="-1">三、七类 SI 问题：现象、机理与观测 <a class="header-anchor" href="#三七类-si-问题现象机理与观测" aria-label="Permalink to &quot;三、七类 SI 问题：现象、机理与观测&quot;">​</a></h2><h3 id="_31-总览" tabindex="-1">3.1 总览 <a class="header-anchor" href="#_31-总览" aria-label="Permalink to &quot;3.1 总览&quot;">​</a></h3><ul><li><strong>电源噪声</strong>：同步切换噪声、地弹、电源反弹、轨道塌陷。</li><li><strong>信号延时</strong>：传播延时偏了，导致时序问题。</li><li><strong>串扰</strong>：相邻走线之间的感性耦合与容性耦合。</li><li><strong>振铃</strong>：达到稳定之前来回震荡。</li><li><strong>非单调性</strong>：波形不再单向上升或下降——回勾、台阶。</li><li><strong>过冲与下冲</strong>：超出稳定值，或低于低电平的瞬态行为。</li><li><strong>衰减</strong>：信号强度随频率逐渐降低，带宽变窄。</li></ul><p>怎么观测：板子做完用示波器看波形；仿真侧用 ADS、Sigrity 这类软件看。</p><p>产品上怎么暴露？有时候工作、有时候不工作；正常工作两小时就死机、重启又好了；样板调试阶段正常、量产却失败；公司调正常、客户现场不正常；前批 PVT 正常、新批次不正常——这些都是可靠性不强的 SI 问题。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093436-786a67fb-0d3c-44e8-b17b-39359f477c66.png" alt="七类现象"></p><h3 id="_32-过冲与下冲" tabindex="-1">3.2 过冲与下冲 <a class="header-anchor" href="#_32-过冲与下冲" aria-label="Permalink to &quot;3.2 过冲与下冲&quot;">​</a></h3><p>过冲和下冲是信号完整性分析里最重要的两个概念，表现的是信号传输时非预期的瞬态行为。</p><ul><li><strong>过冲 overshoot</strong>：信号在达到稳定值之前，超出稳定值的现象，一般发生在上升沿或下降沿。</li><li><strong>下冲 undershoot</strong>：从高切换到低时，比低电平还低——方向相反，机理一样。</li></ul><p>根因都是电路里的寄生参数：有电容、有电感，信号就会在到达最终值之前冲过头。危害是接收器误触发、错误解释信号状态——数字电路里就是逻辑判断错误：本来是低，被判成高电平。</p><p>三条对策：</p><ul><li><strong>优化电路布局</strong>：让每个地方的介质一样、走线宽度一样、间距一样，每一点的寄生参数就一样了。</li><li><strong>阻抗匹配</strong>：确保信号源、传输线、负载之间阻抗匹配，减少反射，用串联终端、并联终端。</li><li><strong>电源和地的稳定</strong>：电源地不波动，就不会有这个问题。</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093598-35cf1307-995e-4f98-9f3d-3374120896ed.png" alt="过冲与下冲"></p><h3 id="_33-振铃" tabindex="-1">3.3 振铃 <a class="header-anchor" href="#_33-振铃" aria-label="Permalink to &quot;3.3 振铃&quot;">​</a></h3><p>振铃，是信号在达到稳定之前出现的一串震荡——类似于物理上的弹簧振子，或者钟摆的震动。</p><p>它与多种因素有关，可以通过适当的端接、或者改变 PCB 参数来减小。最常见的做法是串一个电阻、或者串一个电容：震荡多半来自电感与电容的谐振，加个电阻就把能量消耗掉了。</p><p>但它<strong>不可能被完全消除</strong>——因为寄生参数始终存在，必然会有震荡。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093662-362b6176-d6c7-4236-9746-e4e87a82a737.png" alt="振铃"></p><h3 id="_34-非单调性回勾与台阶" tabindex="-1">3.4 非单调性：回勾与台阶 <a class="header-anchor" href="#_34-非单调性回勾与台阶" aria-label="Permalink to &quot;3.4 非单调性：回勾与台阶&quot;">​</a></h3><p>非单调性，指信号传输过程中波形不再保持单一方向的上升或下降，或者出现多个峰值、谷值，使波形变得复杂。</p><ul><li><strong>回勾</strong>：本来在往上走，突然掉下来，然后又上去。</li><li><strong>台阶</strong>：走到一半不往上走了，停一段时间再继续往上。</li></ul><p>数字电路里理想的波形应当是单调的：从低电平平滑过渡到高电平，或者从高电平平滑过渡到低电平，不出现额外波动。</p><p>回勾和台阶都属于信号完整性的表征现象——在图上一眼就能看出来。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093875-0d3d985b-ac30-48df-9362-c8900f0b908e.png" alt="非单调性"></p><h3 id="_35-串扰" tabindex="-1">3.5 串扰 <a class="header-anchor" href="#_35-串扰" aria-label="Permalink to &quot;3.5 串扰&quot;">​</a></h3><p>串扰（cross talk）是电子电路里常见的一种噪声现象：两条相邻的线之间产生了不必要的耦合。耦合有两条路径：</p><ul><li><strong>感性耦合</strong>：通过电感。电感会阻碍电流的变化，所以它引发的是耦合电流。</li><li><strong>容性耦合</strong>：通过电容。电容要充放电，所以它引发的是耦合电压。</li></ul><p>按位置分两种：<strong>近端串扰</strong>——相邻的走线把信号影响到了本端；<strong>远端串扰</strong>——相邻走线的信号影响到了另外一端（接收端或发送端）。</p><p>串扰主要发生在高速数字电路里，尤其是高密度布线的 PCB——信号线之间的间距越近，发生串扰的可能性越大。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200093931-010883b1-5349-4012-8d64-67373c3b5d6e.png" alt="串扰"></p><h3 id="_36-串扰的应对" tabindex="-1">3.6 串扰的应对 <a class="header-anchor" href="#_36-串扰的应对" aria-label="Permalink to &quot;3.6 串扰的应对&quot;">​</a></h3><p>按优先级排：</p><ol><li><strong>首选增加间距</strong>：两根线之间的距离大了，耦合的电感和电容就小了——这是最好的方式。</li><li><strong>次选使用屏蔽（包地）</strong>：在相邻信号之间放屏蔽线或地线，减少电磁场之间的耦合，尤其是时钟线这种频率比较高的走线。</li><li><strong>使用差分信号</strong>：PCIe、Type-C 都是高速差分——干扰会在接收端相互抵消。</li><li><strong>配合阻抗控制</strong>：保证传输线阻抗连续，避免阻抗突变引起串扰。</li><li><strong>合理规划走线顺序</strong>：同一类型的线组在一起，不同类型的不要组在一起。</li></ol><p>差分为什么能抵消干扰？两根线大小相等、方向相反：一根从 1 走，另一根就从 0 走。你在这两根线上叠加干扰——这边叠加了，那边也叠加了；取值的时候取的是两根正负的差值，一减，耦合进来的共模噪声就没了。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094115-3430777a-a122-4f43-b557-d17ff65155c8.png" alt="串扰对策与 3W 原则"></p><h3 id="_37-衰减" tabindex="-1">3.7 衰减 <a class="header-anchor" href="#_37-衰减" aria-label="Permalink to &quot;3.7 衰减&quot;">​</a></h3><p>由于某些因素导致信号强度逐渐降低，就是信号衰减。两个主因：导电轨迹的电阻（趋肤效应在较高频会加剧），以及耗散因子 Df 引起的损耗。这种损耗随频率增加而增加——<strong>高频分量比低频分量衰减得更多</strong>。</p><p>后果很直接：高频掉了，只剩低频，带宽就变窄了。举例：原本带宽从 10 K 到 1 千兆。10 K 没衰减，高频衰减完了，只能到 800 兆还有信号——相当于衰减掉 200 兆。带宽变窄，信号就失真。</p><p>两个对策：选择正确的低损耗高频材料；走 10 度走线——在服务器主板、电脑主板上常见这种几何形状，目的是解决趋肤效应和玻纤效应。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094231-8a2b4117-833c-451d-8703-ddbc599ae2ed.png" alt="衰减与带宽"></p><h3 id="_38-传播延时" tabindex="-1">3.8 传播延时 <a class="header-anchor" href="#_38-传播延时" aria-label="Permalink to &quot;3.8 传播延时&quot;">​</a></h3><p>传播延时（signal delay），是信号从发送端（驱动器）传到接收端（负载）所需的时间。信号传输对电脑性能有重要影响，尤其在高速数字电路里：延时会导致时序问题、信号失真、数据错误。</p><table tabindex="0"><thead><tr><th>影响因素</th><th>怎么影响</th></tr></thead><tbody><tr><td>介质特性</td><td>不同材料传播速度不同，介质的介电常数是决定传播速度的关键因素之一</td></tr><tr><td>导体特性</td><td>铜线的电阻产生损耗（I²R）；寄生电感储存能量、阻碍变化，影响上升与下降时间</td></tr><tr><td>信号长度</td><td>传输距离越长，所需时间越长</td></tr><tr><td>上升沿速度</td><td>边沿变化越快，信号到达稳定所需时间越短；变化越慢越不稳定</td></tr><tr><td>驱动器与接收器</td><td>驱动器的驱动能力、接收器的输入特性都会影响信号</td></tr><tr><td>温度与频率</td><td>温度以及信号的频率同样会产生这种现象</td></tr></tbody></table><p>怎么控制延时：</p><ul><li><strong>做等长</strong>——用蛇形线绕线，让同组信号虽然都有延时，但延时时间一样，减少信号偏移和采样错误。</li><li><strong>选择高速板材</strong>、损耗比较小的材料，也就是 Df 值小的板材。</li><li><strong>优化叠层</strong>：调整层叠结构和布线策略，提高信号传播速度，比如走表层就会快一些。</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094157-de0a2b83-97f8-45ce-85f1-c9a52b1f099b.png" alt="传播延时"></p><h3 id="_39-介质特性为什么走在表层的信号更快" tabindex="-1">3.9 介质特性：为什么走在表层的信号更快 <a class="header-anchor" href="#_39-介质特性为什么走在表层的信号更快" aria-label="Permalink to &quot;3.9 介质特性：为什么走在表层的信号更快&quot;">​</a></h3><p><strong>表层（微带线）</strong>：上面是空气，εr ≈ 1；下面是 PP / 芯板，εr ≈ 4.2。两者中和，平均之后等效介电常数低于 4.2。介电常数低 → 跑得快。</p><p><strong>内层（带状线）</strong>：上面是 PP / 芯板，下面也是 PP / 芯板。两侧都是 4.2，平均之后还是 4.2。介电常数就是 4.2 → 相对慢一些。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>微带线：εeff &lt; 4.2　　｜　　内层线：εeff = 4.2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>常规 FR4 的介电常数是 4.2。所以想让信号跑得快一点，可以走在表层——代价是微带线只有一个参考平面。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094352-761499ea-e9bc-48d5-ba36-96a899236d7d.png" alt="介质特性"></p><h3 id="_310-电源噪声一同步切换噪声" tabindex="-1">3.10 电源噪声（一）：同步切换噪声 <a class="header-anchor" href="#_310-电源噪声一同步切换噪声" aria-label="Permalink to &quot;3.10 电源噪声（一）：同步切换噪声&quot;">​</a></h3><p>电源噪声，是电源线上出现的非预期的电压波动或稳态变化。第一个来源：同步切换噪声。</p><p>数字电路里，大量逻辑门 IC、MOS 管同时切换：从 0 到 1，或者从 1 到 0。切换瞬间，电平翻转，电流发生快速变化。原本导通的开关突然关断，电流从一个很大的值瞬间变成 0——这就是一个很大的 dI/dt。电流变了，电压就跟着波动，从而影响电路的性能和完整性。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U = L · dI/dt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>电源和地平面有寄生电感，电流变化时就会产生电压降——这个电压叠加在电源上，电平就不稳了。所以，走线上的寄生电感越大、电流变化率越大，叠加到电源上的压降就越明显。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094474-25f36280-8f4a-40e7-99ae-2f64e62051bb.png" alt="同步切换噪声"></p><h3 id="_311-地弹电源反弹轨道塌陷" tabindex="-1">3.11 地弹、电源反弹、轨道塌陷 <a class="header-anchor" href="#_311-地弹电源反弹轨道塌陷" aria-label="Permalink to &quot;3.11 地弹、电源反弹、轨道塌陷&quot;">​</a></h3><ul><li><strong>地弹</strong>：信号沿传输线传播时，返回电流要流过地平面或返回路径，而这条路径上有阻抗：地线有电阻、过孔有阻抗、平面不连续也会产生阻抗。零电位里藏了这些阻抗，于是 0 伏不再是 0 伏——它会在 0 伏上下波动。</li><li><strong>电源反弹</strong>：同一个道理，本来是 5 伏，它也在波动，像弹簧一样弹来弹去。</li><li><strong>轨道塌陷</strong>：由于同步切换噪声或其他电源噪声，电源轨或者地轨会暂时性下降。比如高电平 3.3 伏、0 伏在下面，波动大到维持不住 3.3 伏，掉到 2.8 伏——往下掉了很多。</li></ul><p>共同场景：大量电子元件（比如 MOS 管）同时切换，电流快速变化，引起电源上的电压波动。信号质量对它们都有严格的要求。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地弹：信号由高到低变化，在 0 伏附近弹　｜　电源反弹：VDD 从低到高弹</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094767-1295abf4-efd3-4407-b3d0-c330413a3f4e.png" alt="地弹、电源反弹、轨道塌陷"></p><hr><h2 id="四规避措施" tabindex="-1">四、规避措施 <a class="header-anchor" href="#四规避措施" aria-label="Permalink to &quot;四、规避措施&quot;">​</a></h2><h3 id="_41-五条措施总览" tabindex="-1">4.1 五条措施总览 <a class="header-anchor" href="#_41-五条措施总览" aria-label="Permalink to &quot;4.1 五条措施总览&quot;">​</a></h3><p>前面列出的现象——电源噪声（同步切换噪声、地弹、电源反弹、轨道塌陷）、信号延时、串扰、振铃、非单调性、过冲下冲——全都能靠下面五条来规避。</p><ol><li><strong>统一阻抗设计</strong>：保证每个信号在传输过程中阻抗连续，这是高速 PCB 里最关键的一点。</li><li><strong>避免阻抗不连续</strong>：急剧的转弯、过孔、分支都会引发突变；用渐变过渡。</li><li><strong>降低走线串扰</strong>：增加间距，用地线或平面做屏蔽。</li><li><strong>控制衰减与延时</strong>：选低介电损耗材料，优化走线长度，做等长。</li><li><strong>叠层与电源地设计</strong>：内层作电源层和地层提供屏蔽，去耦电容压噪声。</li></ol><p><strong>阻抗匹配是重中之重</strong>：不一定是 50 欧，60 欧也行——从驱动端一路走到接收端都是 60 欧，就是匹配。怕的是中途变。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094647-f91a4d3f-77cb-404f-8019-b4269b0e6867.png" alt="五条措施"></p><h3 id="_42-措施一统一阻抗设计避免阻抗不连续" tabindex="-1">4.2 措施一：统一阻抗设计，避免阻抗不连续 <a class="header-anchor" href="#_42-措施一统一阻抗设计避免阻抗不连续" aria-label="Permalink to &quot;4.2 措施一：统一阻抗设计，避免阻抗不连续&quot;">​</a></h3><p>统一阻抗，具体要统一什么：</p><table tabindex="0"><thead><tr><th>看哪条路径</th><th>要统一的东西</th></tr></thead><tbody><tr><td>信号路径</td><td>线宽一致；换孔尽量在同一位置；走一节的长度也保持一致</td></tr><tr><td>返回路径</td><td>参考平面不变，距离不变——别一会儿参考这层地，一会儿又参考另一层地</td></tr><tr><td>工艺参数</td><td>走线铜厚一致：表层是 1 盎司铜，换到第三层也要是 1 盎司铜</td></tr><tr><td>线型</td><td>信号与返回路径应设定为同一种传输线类型：走带状线就都走带状线，表层尽量少走线</td></tr></tbody></table><p>再配合端接匹配：源端加电阻，终端加电阻或电阻加电容把能量吸收掉。跨分割会让回流绕圈，返回路径变得很大，所以参考平面要统一、走线不要跨分割。</p><p>避免阻抗不连续的做法：</p><ul><li><strong>少打孔</strong>：过孔会造成阻抗往下掉；能用小孔、盲埋孔就更好。</li><li><strong>减少分支</strong>：分支会产生额外长度，多点使用时走菊花链——复位信号、使能信号都是这么走的。</li><li>不要走直角和锐角，用直线和平滑曲线（45 度或圆弧）。</li><li>焊盘变宽的地方（连接器引脚、ESD 器件）也是阻抗突变，太宽时就把焊盘下面的铜挖掉。</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094824-7b1d8972-b12e-48da-a840-2f038a69c6d1.png" alt="统一阻抗设计"></p><h3 id="_43-措施二降低走线串扰" tabindex="-1">4.3 措施二：降低走线串扰 <a class="header-anchor" href="#_43-措施二降低走线串扰" aria-label="Permalink to &quot;4.3 措施二：降低走线串扰&quot;">​</a></h3><ul><li>最核心一条：保证 <strong>3W 原则</strong>——从走线中心算起，线宽的 3 倍。</li><li>包地并增加间距；差分走线；在信号线之间放置地线或地平面，提供低阻抗路径。</li><li>优化叠层：把线走在内层，两边都是地平面。</li><li>控制并行长度：不要让两根线并排走太长。</li></ul><p>为什么不可能每根线都包地？因为走线时空间往往不够——所以 3W 才是最广泛使用的措施。</p><h3 id="_44-措施三控制衰减与延时" tabindex="-1">4.4 措施三：控制衰减与延时 <a class="header-anchor" href="#_44-措施三控制衰减与延时" aria-label="Permalink to &quot;4.4 措施三：控制衰减与延时&quot;">​</a></h3><ul><li><strong>衰减</strong>：选低 Df 值的板材；走线不要走太长；用 10 度走线对付趋肤效应与玻纤效应。</li><li><strong>延时</strong>：做等长（蛇形线）；优化叠层与布线策略提高传播速度，比如走表层会快一些。</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200094928-4d90db06-7eeb-4db7-8051-8506039c767e.png" alt="压串扰与控衰减延时"></p><h3 id="_45-措施四叠层设计要点" tabindex="-1">4.5 措施四：叠层设计要点 <a class="header-anchor" href="#_45-措施四叠层设计要点" aria-label="Permalink to &quot;4.5 措施四：叠层设计要点&quot;">​</a></h3><ul><li><strong>阻抗最小化</strong>：减少电源平面的压降，让电源没有噪声、没有波动——阻抗越小 I²R 越小。</li><li>走线宽度要够，避免过热。</li><li>平面保持连续，不要分割得太碎。</li><li>过孔合理布局，电源处理时多打过孔，降低电感。</li><li>层间互联要注意走线长度。</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Z = √(L / C)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>平面挨得越近、相对面积越大 → C 越大 → 阻抗最低 → 高频特性最优异。</p><p>电源与地要紧耦合，不要小于 5 mil；尽量避免两个相邻的电源层，实在避不开就把层间距拉大。工作频率超过 500 兆赫兹后，主要就靠平板电容滤波。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200095046-75435124-c195-42d7-a9c4-a3cdc7ea423a.png" alt="叠层设计"></p><hr><h2 id="五电源完整性" tabindex="-1">五、电源完整性 <a class="header-anchor" href="#五电源完整性" aria-label="Permalink to &quot;五、电源完整性&quot;">​</a></h2><h3 id="_51-电源树与-pdn" tabindex="-1">5.1 电源树与 PDN <a class="header-anchor" href="#_51-电源树与-pdn" aria-label="Permalink to &quot;5.1 电源树与 PDN&quot;">​</a></h3><p>电源完整性要解决的是：电压稳定、电流承载能力、阻抗控制、散热、信号完整性、EMI、可靠性——其实跟信号完整性是一个道理。</p><p><strong>先看电源树 power tree</strong>。一般在原理图每一页的前面都有。对着它看电源的分布情况：转换效率、纹波电流大小、大电源与核心电源在哪里，以及数字电源和模拟电源有没有做分区设计。</p><p><strong>再研究 PDN（电源的阻抗）</strong>：</p><ul><li>从电源模块到 IC 的线路上一定有电阻——不走线才没有电阻。这就是直流压降 IR。</li><li>负载电流不是固定值，是不断变化的，所以 IR drop 也不是固定值。</li><li>具有一定频谱宽度的波动电流通过 PDN 的复阻抗，同样会产生压降。</li><li>这个压降意味着：稳压器输出的恒定电压，芯片根本得不到——在进芯片之前就已经变了。</li><li>所以要保证芯片焊盘上的电压变化小于电压容限（比如 5 伏允许正负百分之几的波动）。</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>电源 3 部分：源头 → 传播路径 → 负载端</span></span>
<span class="line"><span>仿真工具：Sigrity 有专门仿 PDN 的模块</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200095205-7d1f78b1-134d-41d6-bb9b-df3890d648a5.png" alt="电源树与 PDN"></p><h3 id="_52-电源分割与-20h-原则" tabindex="-1">5.2 电源分割与 20H 原则 <a class="header-anchor" href="#_52-电源分割与-20h-原则" aria-label="Permalink to &quot;5.2 电源分割与 20H 原则&quot;">​</a></h3><p>分割时注意这些：</p><ul><li>小范围特定电源（比如 IC 芯片的核心工作电压）不要在电源平面分割，直接在走线层处理。</li><li>不要圈成哑铃状——两头铜很大、中间细成一丢丢。中间窄了电流密度就大，I²R 压降就大：左边还是 5 伏，到这儿可能只剩 4.5 伏。</li><li>分割宽度：电压大于 12 伏时要宽一点，相当于电气间隙与爬电距离；模拟电源与数字电源之间加大 2 毫米。</li><li>分割带边缘要检查：载流通道够不够、过孔数量够不够、需不需要削盘——有焊盘的地方很窄，削掉盘就变宽了。</li></ul><p><strong>走线守 3W，电源分割守 20H</strong>；做不到 20H 就内缩 1 毫米，同样能解决板边辐射问题。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200095169-7aa50a9c-f616-4e3e-815c-9ca3190b7fa9.png" alt="电源分割与 20H"></p><h3 id="_53-过孔寄生反焊盘盲埋孔与背钻" tabindex="-1">5.3 过孔寄生：反焊盘、盲埋孔与背钻 <a class="header-anchor" href="#_53-过孔寄生反焊盘盲埋孔与背钻" aria-label="Permalink to &quot;5.3 过孔寄生：反焊盘、盲埋孔与背钻&quot;">​</a></h3><p><strong>寄生电容</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C ≈ 1.41 · εr · T · D2 / (D1 − D2)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>D1＝反焊盘直径，D2＝焊盘直径。把 D1 做大、D2 做小 → 电容变小。</p><p><strong>寄生电感</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L ≈ 5.08 · h · [ln(4h/d) + 1]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>h＝过孔长度，d＝钻孔直径。孔越短、直径越小 → 电感越小。</p><p>电感的危害是削弱旁路电容的作用：电压已经往下掉了，电容想补，但电感阻碍电流变化、补不进去，滤波变差，电源就有噪声。所以：上盲埋孔（钻孔只有 0.1）、用背钻把多余的残端 stub 钻掉。</p><p>理论上过孔越小越好，但 6-8 的孔在 1.6 毫米板上根本钻不穿，最终要按工艺来。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200095291-3620a3f3-70dc-494b-8be4-463c7f7ab837.png" alt="过孔寄生"></p><h3 id="_54-去耦电容怎么放" tabindex="-1">5.4 去耦电容怎么放 <a class="header-anchor" href="#_54-去耦电容怎么放" aria-label="Permalink to &quot;5.4 去耦电容怎么放&quot;">​</a></h3><p>电源管脚旁边为什么要加一个小电容？因为同步切换时 dI/dt 会造成电感压降、甚至轨道塌陷——电容先把能量存起来，电压往下掉的时候由它马上补上。</p><ul><li>芯片电源管脚可以加粗到 8，增加走线宽度就能降低阻抗。</li><li>减小引线长度、成对出现、减少环路。</li><li>大电容分布在芯片周围，小电容放在管脚附近。</li><li>电容比较大时打两个过孔甚至多个过孔：相当于两根线加粗，两个电感并联，电感就小了。</li><li>电容的引线要短、要粗——越短越粗，寄生电感越小。</li></ul><p>以后看到电源模块旁边已经有滤波电容、芯片旁边还要再放一个，就知道原因了：走线太长，寄生电感太大，就近的那个电容才能真正补得上。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200095357-a696ef59-b4fa-4dca-acd8-519ecb00f4bc.png" alt="去耦电容"></p><hr><h2 id="六一页速查表" tabindex="-1">六、一页速查表 <a class="header-anchor" href="#六一页速查表" aria-label="Permalink to &quot;六、一页速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>必须记住的</th></tr></thead><tbody><tr><td>SI / PI</td><td>SI＝收发波形一致；PI＝给芯片稳定无噪声的电源。SI 只针对高速信号</td></tr><tr><td>判定标准</td><td>高速电路：频率超过 50 MHz 且占总系统 1/3；高速信号：传播延时大于上升沿的 1/2</td></tr><tr><td>速算口径</td><td>1 ns ≈ 6000 mil；上升时间取 10%→90%（IBIS 常取 20%→80%）</td></tr><tr><td>传输线</td><td>信号路径＋返回路径；返回路径＝任何导体，不只是地</td></tr><tr><td>回流走哪儿</td><td>集中在走线正下方；走线下面邻近层要有完整参考平面</td></tr><tr><td>过冲下冲</td><td>寄生参数引起；对策：布局一致化、阻抗匹配、电源地稳定</td></tr><tr><td>振铃 / 非单调</td><td>振铃靠端接耗能减小，不可能消除；非单调＝回勾与台阶</td></tr><tr><td>串扰</td><td>分近端与远端；对策：3W 原则（5 mil → 15 mil）、包地、差分、阻抗连续、走线排序</td></tr><tr><td>衰减 / 延时</td><td>趋肤效应与 Df 让高频先掉、带宽变窄；延时靠等长与低损耗板材控制</td></tr><tr><td>电源噪声</td><td>同步切换噪声（L·dI/dt）、地弹、电源反弹、轨道塌陷</td></tr><tr><td>叠层 / 电源</td><td>电源与地不超 5 mil 紧耦合；Z＝√(L/C)；避免两个电源层相邻</td></tr><tr><td>分割原则</td><td>走线 3W，电源分割 20H；20H 关住 70% 电场，100H 达 98%</td></tr><tr><td>过孔</td><td>反焊盘 D1 大、焊盘 D2 小 → 电容小；孔短径小 → 电感小；盲埋孔 + 背钻</td></tr><tr><td>去耦电容</td><td>就近管脚、引线短粗、多打过孔、大小电容分工</td></tr></tbody></table><p><img src="https://cdn.nlark.com/yuque/0/2026/png/2113993/1791200095543-d17e489f-e5d8-4707-9780-c478f96518fe.png" alt="一页速查"></p><hr><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>这份内容里，真正值得记住的数字其实只有几个：<strong>50 MHz 与 1/3 系统占比</strong>、<strong>6000 mil 对应 1 ns</strong>、<strong>上升沿的 1/2</strong>、<strong>3W</strong>、<strong>20H</strong>、<strong>5 mil</strong>。剩下的都是从这几个数字长出来的判断。</p><p>如果只挑一条最重要的：<strong>让阻抗从头到尾保持一致</strong>。过冲、振铃、串扰、衰减、延时，绝大多数现象的根源都可以追溯到「阻抗在中途变了」——一次跨分割、一个过孔、一段分支、一块变宽的焊盘。</p>`,215)])])}const u=t(l,[["render",s]]);export{g as __pageData,u as default};
